#!/bin/sh
set -eu
mkdir -p /backups
while true; do
  filename="/backups/barberflow-$(date -u +%Y%m%d-%H%M%S).dump"
  if pg_dump --format=custom --file="$filename.partial" && pg_restore --list "$filename.partial" > /dev/null; then
    mv "$filename.partial" "$filename"
    echo "Backup PostgreSQL verificado: $filename"
    # Only files generated by this service are retained or removed.
    find /backups -maxdepth 1 -type f -name 'barberflow-*.dump' -mtime +14 -delete
  else
    echo 'Falha no backup PostgreSQL; os backups anteriores foram preservados.' >&2
  fi
  sleep "${BACKUP_INTERVAL_SECONDS:-86400}"
done
